"""Report the actual one-expert rerun, retaining historical signed outcomes."""
import json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from scripts.stvg_single_referdino_bidirectional256_common_v1 import D,P,read,put,sha,load,verify,ROWS

def main():
 p=verify();r=read(P/'RESULTS_PUBLIC.json');assert read(P/'ROOT_AUDIT_PUBLIC.json')['status']=='pass';profiles={ds:read(D/f'PROFILE_{ds}.json')for ds in ['hc2','vidstg']};ledgers={ds:[read(f)for f in sorted(D.glob(f'COST_{ds}_*.json'))]for ds in ['hc2','vidstg']};cost=dict(profiles=profiles,worker_ledgers=ledgers,profile_queries_are_primary_not_duplicate=True,features_reused_initially=197,missing_Vid_Source224_features_completed=59,new_Source224_queries=61,new_Source448_queries=2,primary_feature_inputs_reused_without_new_Source=195,new_ReferDINO_query_forwards=2,new_ReferDINO_frames=16,primary_native_teacher_caches_reused=254,new_independent_GroundingDINO_calls=0,primary_fits=256,primary_updates=8960,prior_paused_search_seconds=287.90187390497886,prior_paused_search_compatibility_updates=40,prior_search_new_parameter_fits=0,not_panel_mean_end_to_end_latency=True)
 decision=dict(status='completed_single_expert_rerun',expert_count=1,same_eight_evidence=True,parameters=dict(hc2_steps=40,vidstg_steps=30,lr=.01,tau=.2,scales=[.05,.25],M=32,seed=41,alpha=1),tuning_paused=True,independent_confirmation=False,automatic_followup=False,production_registry_promotion=False,interpretation={})
 lines=['# Single ReferDINO initialization and OPD: paired bidirectional evaluation','', 'The independent GroundingDINO stage is removed in the new executable path. One frozen native ReferDINO selected track at the original eight positions initializes E_Ref and supplies the same eight pseudo boxes for actual current-student OPD. Strong and MBR remain unchanged. All256 parents were resealed before GT evaluation. These are exposed development panels, not independent tests.','', '## Frozen implementation and parameters','', 'TA-STVG Source checkpoints are unchanged in both transfer directions. HC40 and Vid30 updates; Adam0.01, tau0.2, scales(0.05,0.25),32 candidates per anchor, seed41, output alpha1. Only8×256 query-local content states are optimized; all network weights are frozen. Vid30 was selected from the prior old-initialization nine-grid. The later lr/tau search was paused before new parameter fits; no such optimum is claimed.','', 'E_Ref uses the inherited truncated robust global four-dimensional correction, now with eight singleton ReferDINO references. It preserves the source-domain scale/truncation; no ReferDINO-specific or target-GT recalibration. Within-frame relative confidence costs are zero for singleton references. Geometric rejection affects initialization support but does not select different OPD evidence.','', '## Five matched rows','', '| Direction / method | Full vIoU % | tIoU % | Fixed actual-node sIoU % | Unobserved actual-node sIoU % |','|---|---:|---:|---:|---:|']
 for ds,g in r['directions'].items():
  for arm in ROWS:
   x=g['means'][arm];lines.append(f"| {g['direction']} / {arm} | {100*x['v']:.6f} | {100*x['t']:.6f} | {100*x['fixed_actual_sIoU']:.6f} | {100*x['unobserved_actual_sIoU']:.6f} |")
 lines+=['','Five rows have the original common physical frame support and MBR. Full and Without_spatial_adaptation share Strong exactly; their difference isolates adaptation after the new E_Ref. Source and Temporal_only reproduce the prior scores exactly. All failed, zero-overlap, rejected-initialization and harmful parents remain.','', '## Paired differences, parent bootstrap95% intervals','', '| Direction / comparison | vIoU delta pp [CI95] | Unobserved actual sIoU delta pp [CI95] | Positive / negative / tied | Below −5pp |','|---|---:|---:|---:|---:|']
 for ds,g in r['directions'].items():
  for name,x in g['paired'].items():
   v,u=x['v'],x['unobserved_actual_sIoU'];t=x['tail'];lines.append(f"| {g['direction']} / {name} | {v['mean']:+.6f} [{v['CI95'][0]:+.6f}, {v['CI95'][1]:+.6f}] | {u['mean']:+.6f} [{u['CI95'][0]:+.6f}, {u['CI95'][1]:+.6f}] | {t['positive']} / {t['negative']} / {t['unchanged']} | {t['below_minus5']} |")
  x=g['paired']['Full_minus_Without_spatial_adaptation'];decision['interpretation'][ds]=dict(Full_minus_Source=g['paired']['Full_minus_Source']['v'],adaptation_minus_ERef_Strong=x['v'],adaptation_CI_excludes_zero_positive=x['v']['CI95'][0]>0,historical_matched_steps=g['paired']['New_Full_minus_old_Full_matched_steps']['v'],no_independent_on_policy_claim=True)
 lines+=['','Historical comparisons use the saved two-expert predictions on the exact same parents. New_Full_minus_old_Full40 changes initialization and, in Vid, the stopping budget. New_Full_minus_old_Full_matched_steps instead compares Vid30 to old Vid30; HC remains40 in both. These are historical matched controls, not new independently selected confirmations.','', '## Interpretation and severe cases','']
 for ds,g in r['directions'].items():
  x=g['paired']['Full_minus_Without_spatial_adaptation'];t=x['tail'];supported=x['v']['CI95'][0]>0;lines.append(f"{g['direction']}: Full−E_Ref+Strong {x['v']['mean']:+.6f}pp; {'positive paired interval on this exposed panel' if supported else 'stable positive incremental adaptation is not established'}. Positive contributions {t['positive_contribution_pp']:+.6f}pp; negative contributions {t['negative_contribution_pp']:+.6f}pp. Worst signed cases: "+', '.join(f"{v['alias']} {v['delta_pp']:+.4f}pp"for v in t['worst'])+'.')
  old_adapt=sum(100*(row['historical']['old_two_expert_Full_matched_steps']['v']-row['historical']['old_two_expert_E_Strong']['v'])for row in g['rows'])/128
  init_delta=g['paired']['New_ERef_minus_old_E']['v']['mean'];adapt_change=x['v']['mean']-old_adapt
  assert abs(init_delta+adapt_change-g['paired']['New_Full_minus_old_Full_matched_steps']['v']['mean'])<1e-10
  decision['interpretation'][ds]['matched_step_mean_decomposition_pp']=dict(initialization_change=init_delta,adaptation_contribution_change=adapt_change,old_adaptation=old_adapt,new_adaptation=x['v']['mean'])
  lines.append(f"Exact mean decomposition versus the old matched-step method: initialization {init_delta:+.6f}pp + change in adaptation contribution {adapt_change:+.6f}pp = complete-method change {init_delta+adapt_change:+.6f}pp. This is an accounting identity, not a causal attribution to one hyperparameter.")
  if ds=='vidstg':
   row=next(x for x in g['rows']if x['alias']=='BV041');lines.append('BV041: new E_Ref+Strong '+f"{100*row['values']['Without_spatial_adaptation']['v']:.6f}% → Full {100*row['values']['Full']['v']:.6f}%; historical old E+Strong {100*row['historical']['old_two_expert_E_Strong']['v']:.6f}%, old Full30 {100*row['historical']['old_two_expert_Full_matched_steps']['v']:.6f}%, old Full40 {100*row['historical']['old_two_expert_Full40']['v']:.6f}%." )
 lines+=['','No Fixed/Live contrast is added in this replacement round; gains over E_Ref measure this adaptation component, not an independent proof of on-policy superiority. Changing expert initialization can itself improve or harm outcomes, and a positive Full−Source cannot by itself establish OPD value. No new parameter search is launched from these results.','', '## Costs and evidence accounting','', '| Direction | Complete first-query wall s | Source224 s | Source448 s | ReferDINO process incl. load s | OPD fit s | Peak allocated GiB |','|---|---:|---:|---:|---:|---:|---:|']
 for ds,x in profiles.items():
  c=x['capture_cost'];lines.append(f"| {ds} | {x['complete_single_seed_wall_seconds']:.6f} | {c['Source224_seconds']:.6f} | {c['Source448_seconds']:.6f} | {c['ReferDINO_process_seconds']:.6f} | {x['adapt_cost']['fit_seconds']:.6f} | {x['peak_GPU_bytes']/2**30:.6f} |")
 lines+=['','These are prelocked first-case full-input profiles, not panel-average deployment latency or a controlled speedup comparison against historical runs. Both deny detector checkpoint access and historical prediction-cache access during the new full pipeline. Their fresh Source, ReferDINO native boxes, E_Ref, Native/Strong posterior and intervals reproduce the prepared evidence exactly; profile predictions count in the256 primary fits. The runtime loads the complete ReferDINO state without its redundant independent detector-checkpoint preload; all learned parameters are covered. ReferDINO retains its native internal architecture.','', f"Actual new fitting:256 fits /8960 updates. Worker wall HC {sum(q['worker_wall_seconds']for q in ledgers['hc2']):.6f}s and Vid {sum(q['worker_wall_seconds']for q in ledgers['vidstg']):.6f}s, including recording and cache handling. Initial Source-feature reuse197;59 missing Vid Source224 caches were regenerated. Two full-chain profiles add two Source448 passes and two ReferDINO8 queries; all other teacher evidence is native-output cache reuse. Independent detector forwards:0. Prior paused-search287.901874s/40 compatibility updates are separate preparation cost; no new parameter trial was completed.",'','## Verification and scope','', 'Independent enumeration verifies256 E_Ref initializations and evidence identity. All8960 actual updates have independent sampling, geometry cost, mixture probability gradient and state-step checks; zero state restores E_Ref. Official evaluator versus dense implementation checks all1280 row predictions; saved-score aggregation, parent bootstrap intervals and signed tails are independently recomputed. Raw teacher caches, video, annotations, parent IDs and original captions are excluded from public export. See RESULTS_PUBLIC.json, AUDIT_PUBLIC.json, INDEPENDENT_SPATIAL_AUDIT_PUBLIC.json, ROOT_AUDIT_PUBLIC.json and COST_PUBLIC.json.','', 'All original predictions, negative reports and production/paper registries remain unchanged. The new package/configuration and root README define the requested one-expert research design; configuration selection does not claim independent effectiveness. Tuning remains stopped pending the result review.']
 put(P/'COST_PUBLIC.json',cost);put(P/'DECISION_PUBLIC.json',decision);put(P/'PROVENANCE_PUBLIC.json',dict(Source_checkpoints=p['checkpoints'],ReferDINO=read(D/'EXPERT_WEIGHT_LOCK.json'),all_original_source_predictions_pinned=True,initialization_source='same eight native selected-track references as OPD',Strong_unchanged=True,source_calibration_inherited_not_new_training=True,exposure={ds:g['exposure']for ds,g in r['directions'].items()}));(P/'REPORT.md').write_text('\n'.join(lines)+'\n');put(P/'CONFIG_PUBLIC.json',p['configs']);print('REPORT_WRITTEN')
if __name__=='__main__':main()
